-- Additional course-specific practice for under-served BBA core and pathway units.
-- All questions are original study material, not official MUST examination questions.
WITH quiz_seed(course_code,title,description) AS (
 VALUES
 ('BFB3150','Ace Practice · Insurance and Risk Management','Original practice on insurable risk, pooling, indemnity and risk controls. Not an official examination paper.'),
 ('SMB3113','Ace Practice · Introduction to Business Statistics','Original applied practice on sampling, descriptive statistics, correlation and distributions.'),
 ('BBS3125','Ace Practice · Principles of Procurement','Original practice grounded in Kenyan public-procurement principles and transparent evaluation.'),
 ('BFC3276','Ace Practice · Introduction to Taxation','Original practice on tax concepts and compliance. Tax rates and deadlines must be checked against current KRA guidance.'),
 ('CIT3251','Ace Practice · Management Information Systems','Original practice on information quality, business systems, controls and decision support.'),
 ('CIT3477','Ace Practice · E-Commerce','Original practice on online conversion, security, payments and customer journeys.'),
 ('BFB3301','Ace Practice · Environmental Issues in Business','Original practice on externalities, life-cycle thinking and environmental management.'),
 ('BFB3351','Ace Practice · Corporate Social Responsibility','Original practice on stakeholders, supply chains, reporting and responsible business.'),
 ('BFB3401','Ace Practice · Cross Cultural Management','Original practice on cultural intelligence, adaptation and communication across contexts.'),
 ('BFB3451','Ace Practice · Corporate Governance','Original practice on board oversight, disclosure, conflicts and accountability.'),
 ('BFC3475','Ace Practice · Management Research Project','Original practice on research questions, literature review, sampling and research ethics.'),
 ('BFB3411','Ace Practice · Project Portfolio Management','Original practice on strategic alignment, portfolio risk, dependencies and benefits.')
),
inserted_quizzes AS (
 INSERT INTO public.ace_quizzes(title,course_code,description,status)
 SELECT s.title,s.course_code,s.description,'published' FROM quiz_seed s
 WHERE NOT EXISTS(SELECT 1 FROM public.ace_quizzes q WHERE q.title=s.title AND q.course_code=s.course_code)
 RETURNING id,course_code,title
),
quiz_ids AS (
 SELECT id,course_code,title FROM inserted_quizzes
 UNION ALL
 SELECT q.id,q.course_code,q.title FROM public.ace_quizzes q JOIN quiz_seed s ON s.course_code=q.course_code AND s.title=q.title
 WHERE NOT EXISTS(SELECT 1 FROM inserted_quizzes i WHERE i.id=q.id)
),
question_seed(course_code,quiz_title,sort_order,prompt,options,correct_index,explanation) AS (
 VALUES
 -- Insurance and Risk Management
 ('BFB3150','Ace Practice · Insurance and Risk Management',1,'Which statement best distinguishes a pure risk from a speculative risk?',ARRAY['A pure risk involves loss or no loss, while a speculative risk can produce gain or loss','A pure risk always produces a profit','A speculative risk cannot be insured in any circumstance','The two terms mean exactly the same thing']::text[],0,'Pure risks involve the possibility of loss or no loss; speculative risks also include the possibility of gain.',1),
 ('BFB3150','Ace Practice · Insurance and Risk Management',2,'Insurable interest generally requires the policyholder to have:',ARRAY['A recognised financial or legal interest in the subject matter insured','A guarantee that no loss can occur','Ownership of every insurance company','The ability to set the insurer’s claims decision']::text[],0,'Insurable interest links the policyholder to a legitimate interest in the insured person or property, as required by the applicable law and policy.',2),
 ('BFB3150','Ace Practice · Insurance and Risk Management',3,'The principle of indemnity is intended mainly to:',ARRAY['Restore the insured to the approximate financial position before a covered loss, subject to policy terms','Allow the insured to profit from every claim','Pay every loss regardless of exclusions','Remove the need to disclose material facts']::text[],0,'Indemnity generally aims to compensate for covered loss rather than create a profit; some insurance classes operate differently.',3),
 ('BFB3150','Ace Practice · Insurance and Risk Management',4,'Risk pooling helps insurers because:',ARRAY['Losses across a sufficiently large group can be estimated more reliably than one person’s loss alone','Every policyholder experiences a loss at the same time','It eliminates uncertainty completely','Premiums no longer need to reflect risk']::text[],0,'Pooling combines many exposures so aggregate losses are more predictable, though severe correlated events can still cause large losses.',4),
 ('BFB3150','Ace Practice · Insurance and Risk Management',5,'A business installs fire alarms, trains staff and separates flammable materials before buying insurance. These actions primarily represent:',ARRAY['Risk prevention and loss mitigation','Risk transfer only','A claim settlement','Adverse selection']::text[],0,'Prevention reduces the likelihood of a loss and mitigation reduces its severity; insurance is a separate risk-transfer mechanism.',5),
 -- Business Statistics
 ('SMB3113','Ace Practice · Introduction to Business Statistics',1,'A dataset contains 18, 19, 20, 21 and 92. Which measure of central tendency is least affected by the extreme value 92?',ARRAY['Arithmetic mean','Median','Range','Standard deviation']::text[],1,'The median is resistant to extreme observations; the mean is pulled upward by the large value.',1),
 ('SMB3113','Ace Practice · Introduction to Business Statistics',2,'A researcher selects every tenth customer from an ordered list after choosing a random starting point. This is:',ARRAY['Systematic sampling','Convenience sampling','Snowball sampling','A complete census']::text[],0,'Systematic sampling selects units at a fixed interval after a random start.',2),
 ('SMB3113','Ace Practice · Introduction to Business Statistics',3,'A correlation coefficient close to zero indicates that:',ARRAY['There is little evidence of a linear relationship in the sample, though other relationships may exist','The variables must be independent in every possible sense','One variable definitely causes the other','The sample contains no measurement error']::text[],0,'A near-zero linear correlation does not rule out nonlinear relationships or prove independence or causation.',3),
 ('SMB3113','Ace Practice · Introduction to Business Statistics',4,'If every value in a dataset is increased by 10, what happens to its standard deviation?',ARRAY['It increases by 10','It decreases by 10','It stays the same','It becomes zero']::text[],2,'Adding the same constant shifts all values but does not change their distances from the mean, so standard deviation is unchanged.',4),
 ('SMB3113','Ace Practice · Introduction to Business Statistics',5,'A survey receives responses only from customers who voluntarily click a feedback link. The main concern is:',ARRAY['Self-selection bias may make respondents unlike the full customer population','The sample is automatically random','The mean cannot be calculated','Every non-response is a positive response']::text[],0,'Voluntary response can overrepresent people with unusually strong experiences or motivation, limiting representativeness.',5),
 -- Procurement
 ('BBS3125','Ace Practice · Principles of Procurement',1,'Article 227 of the Constitution of Kenya requires public procurement to be conducted in accordance with principles including:',ARRAY['Fairness, equity, transparency, competitiveness and cost-effectiveness','Secrecy, personal preference and unlimited discretion','Preference for one supplier without lawful basis','Awarding every contract to the lowest quoted price regardless of requirements']::text[],0,'Article 227 sets constitutional principles for public procurement; the applicable legislation and regulations provide detailed procedures.',1),
 ('BBS3125','Ace Practice · Principles of Procurement',2,'Why should tender evaluation criteria be established and disclosed in the tender documents before bids are evaluated?',ARRAY['To support fair, transparent and consistent assessment against stated requirements','To allow criteria to be changed for a preferred bidder','To avoid recording evaluation decisions','To ensure price is the only possible consideration in every procurement']::text[],0,'Pre-disclosed criteria reduce arbitrary treatment and help make evaluation consistent and auditable.',2),
 ('BBS3125','Ace Practice · Principles of Procurement',3,'A technical specification names one supplier’s product without an objective justification or permitted exception. The main risk is:',ARRAY['Unfairly restricting competition','Increasing transparency automatically','Removing all conflicts of interest','Guaranteeing the best whole-life value']::text[],0,'Specifications should describe legitimate needs and avoid unjustified restrictions on competition.',3),
 ('BBS3125','Ace Practice · Principles of Procurement',4,'Which record most directly supports an auditable procurement decision?',ARRAY['Documented approvals, evaluation records, reasons and contract award evidence','A verbal assurance that the process was fair','A supplier’s marketing brochure alone','A deleted bid register']::text[],0,'Complete records allow authorised reviewers to reconstruct the process and verify compliance.',4),
 ('BBS3125','Ace Practice · Principles of Procurement',5,'A procurement officer discovers that a close relative owns one of the bidding firms. The most appropriate response is to:',ARRAY['Disclose the potential conflict and follow the applicable recusal and procurement rules','Hide the relationship unless another bidder complains','Change the evaluation criteria after bids arrive','Share confidential competitor bids with the relative']::text[],0,'Conflict-of-interest rules protect impartiality; the officer should disclose and follow the prescribed handling process.',5),
 -- Taxation
 ('BFC3276','Ace Practice · Introduction to Taxation',1,'The tax base is best described as:',ARRAY['The amount or value to which a tax rate is applied under the relevant law','The tax authority’s office location','The total number of tax officers','A penalty imposed in every case']::text[],0,'A tax base is the measure on which a tax liability is calculated, as defined by the applicable tax law.',1),
 ('BFC3276','Ace Practice · Introduction to Taxation',2,'PAYE is primarily a mechanism for collecting tax on:',ARRAY['Employment income through withholding by the employer','All retail purchases at a supermarket only','Imported goods only','Company dividends only']::text[],0,'PAYE is a withholding mechanism for employment income; exact obligations and rates depend on current Kenyan law.',2),
 ('BFC3276','Ace Practice · Introduction to Taxation',3,'A taxpayer deliberately conceals taxable income in breach of tax law. This is best described as:',ARRAY['Tax evasion','Ordinary tax planning in every case','A tax credit','A statutory exemption']::text[],0,'Tax evasion involves unlawful concealment or misrepresentation; lawful tax planning uses permitted choices and deductions.',3),
 ('BFC3276','Ace Practice · Introduction to Taxation',4,'For a VAT-registered business, input tax generally refers to:',ARRAY['VAT incurred on eligible business purchases, subject to the law’s deduction rules','The VAT charged on every sale by the business','The company’s profit before tax','A penalty for late filing']::text[],0,'Input tax is VAT on eligible purchases; deductibility depends on registration, documentation and statutory conditions.',4),
 ('BFC3276','Ace Practice · Introduction to Taxation',5,'Before using a tax rate in a 2026 Kenyan tax calculation, a student should:',ARRAY['Check current legislation and the latest KRA guidance for the relevant tax period','Assume every rate from an old textbook remains unchanged','Use the rate from another country','Ignore effective dates and transitional rules']::text[],0,'Rates, thresholds and commencement dates can change through Finance Acts and other instruments, so current authoritative sources matter.',5),
 -- Management Information Systems
 ('CIT3251','Ace Practice · Management Information Systems',1,'A management information system primarily transforms data into:',ARRAY['Useful information for planning, control and decision-making','A guarantee that every decision will be correct','Unrelated files without structure','Only printed receipts']::text[],0,'MIS collects and processes data into information that supports managerial decisions and organisational processes.',1),
 ('CIT3251','Ace Practice · Management Information Systems',2,'Which system is most directly responsible for recording routine sales, payments and inventory transactions?',ARRAY['Transaction Processing System','Executive strategy retreat','Manual brand guidelines','External advertising campaign']::text[],0,'Transaction processing systems capture and process routine operational events that feed other systems.',2),
 ('CIT3251','Ace Practice · Management Information Systems',3,'A dashboard gives a manager a wrong sales total because duplicate customer records were not resolved. This primarily illustrates:',ARRAY['Poor data quality can undermine information and decisions','Dashboards always correct source data automatically','Visual design is more important than accuracy','Duplicate records have no operational impact']::text[],0,'Information quality depends on accurate, complete, consistent and timely source data.',3),
 ('CIT3251','Ace Practice · Management Information Systems',4,'The principle of least privilege means users should receive:',ARRAY['Only the system permissions necessary for their assigned work','Administrator access by default','The same password as every colleague','Permanent access to all customer data']::text[],0,'Least privilege reduces the impact of mistakes and compromised accounts by limiting unnecessary access.',4),
 ('CIT3251','Ace Practice · Management Information Systems',5,'Why should user acceptance testing happen before a new business system is fully rolled out?',ARRAY['To check whether realistic user workflows meet requirements and uncover defects','To replace all security testing','To ensure users never need training','To avoid collecting feedback']::text[],0,'User acceptance testing checks whether the system supports agreed business requirements in realistic scenarios.',5),
 -- E-Commerce
 ('CIT3477','Ace Practice · E-Commerce',1,'An online shop receives 25 orders from 1,000 unique visitors. Its order conversion rate is:',ARRAY['0.25%','2.5%','25%','40%']::text[],1,'Conversion rate = 25 ÷ 1,000 × 100 = 2.5%.',1),
 ('CIT3477','Ace Practice · E-Commerce',2,'HTTPS on a checkout page primarily helps protect:',ARRAY['Data in transit between the browser and website, but it does not prove the seller is trustworthy','The buyer from every form of fraud','The seller from all chargebacks','The accuracy of every product description']::text[],0,'HTTPS encrypts the connection and authenticates the domain certificate; it cannot guarantee honest business practices or secure every endpoint.',2),
 ('CIT3477','Ace Practice · E-Commerce',3,'Which measure is most useful for understanding how many customers begin checkout but leave before placing an order?',ARRAY['Checkout abandonment rate','Employee headcount','Gross fixed assets','Annual depreciation rate']::text[],0,'Checkout abandonment measures the share of checkout starters who do not complete the order.',3),
 ('CIT3477','Ace Practice · E-Commerce',4,'A payment gateway reports successful payment, but the store never confirms inventory availability. Which design issue is most important to address?',ARRAY['Order and inventory states need reliable coordination and clear exception handling','The store should remove all order identifiers','Customers should share passwords with staff','Payment success means the order cannot fail']::text[],0,'A robust checkout coordinates payment, stock reservation and order state, including handling partial failures and refunds.',4),
 ('CIT3477','Ace Practice · E-Commerce',5,'Which is the strongest account-security improvement for a merchant administrator?',ARRAY['Unique strong passwords plus multifactor authentication and role-limited access','One shared password for the whole team','Disabling login alerts and audit logs','Using the same password on every service']::text[],0,'Unique credentials, MFA and least-privilege roles reduce account takeover and limit the damage from compromised credentials.',5),
 -- Environmental Issues in Business
 ('BFB3301','Ace Practice · Environmental Issues in Business',1,'A factory releases pollution whose costs are borne by nearby residents rather than included in the product price. This is:',ARRAY['A negative externality','A positive externality','A sunk accounting cost only','A consumer surplus by definition']::text[],0,'The activity imposes external costs on third parties that are not fully reflected in the market price.',1),
 ('BFB3301','Ace Practice · Environmental Issues in Business',2,'Life-cycle thinking assesses environmental impacts:',ARRAY['Across relevant stages from raw materials and production through use and end-of-life','Only at the point a product is advertised','Only inside the finance department','Without considering supply chains']::text[],0,'Life-cycle assessment considers impacts across multiple stages and helps avoid shifting harm from one stage to another.',2),
 ('BFB3301','Ace Practice · Environmental Issues in Business',3,'Which approach is most consistent with pollution prevention?',ARRAY['Redesigning a process to reduce waste at source before relying on end-of-pipe treatment alone','Increasing waste and measuring it less often','Moving all waste to an unregulated site','Reporting emissions only when customers ask']::text[],0,'Prevention seeks to avoid or reduce pollution at source, often improving resource efficiency as well.',3),
 ('BFB3301','Ace Practice · Environmental Issues in Business',4,'A circular-economy approach places emphasis on:',ARRAY['Keeping products and materials in use through durability, repair, reuse and recovery','Maximising disposal after one use','Treating all resources as unlimited','Ignoring product design']::text[],0,'Circular strategies aim to reduce waste and retain value through reuse, repair, refurbishment and recycling.',4),
 ('BFB3301','Ace Practice · Environmental Issues in Business',5,'An environmental management system is most useful when it:',ARRAY['Sets responsibilities, objectives, monitoring and continual-improvement processes','Replaces all legal obligations','Guarantees zero environmental impact without evidence','Operates only as a public-relations slogan']::text[],0,'A management system provides structured controls and continual improvement; it does not replace legal compliance or prove zero impact.',5),
 -- Corporate Social Responsibility
 ('BFB3351','Ace Practice · Corporate Social Responsibility',1,'A stakeholder approach to business decisions considers:',ARRAY['Groups affected by or able to affect the organisation, not shareholders alone','Only the next quarter’s revenue','Only the preferences of senior managers','Only legal minimums with no wider impacts']::text[],0,'Stakeholder analysis considers impacts on employees, customers, suppliers, communities, investors and other relevant groups.',1),
 ('BFB3351','Ace Practice · Corporate Social Responsibility',2,'A company advertises itself as sustainable but provides no evidence and hides material supply-chain harms. This is most likely:',ARRAY['Greenwashing','Independent assurance','Life-cycle assessment','Stakeholder engagement']::text[],0,'Greenwashing creates a misleading impression of environmental or social performance without adequate evidence.',2),
 ('BFB3351','Ace Practice · Corporate Social Responsibility',3,'Why should a responsible-business programme examine suppliers and contractors?',ARRAY['Risks to people, labour rights and the environment can occur beyond the company’s direct operations','Outsourcing automatically removes all responsibility','Suppliers never affect product quality','Supply chains cannot be influenced by purchasing choices']::text[],0,'Responsible business due diligence considers relevant impacts across operations and business relationships, including supply chains.',3),
 ('BFB3351','Ace Practice · Corporate Social Responsibility',4,'The triple-bottom-line framework is commonly associated with:',ARRAY['People, planet and prosperity/profit','Price, place and promotion only','Assets, liabilities and equity only','Planning, staffing and control only']::text[],0,'The framework broadens performance discussion beyond financial results to social and environmental dimensions.',4),
 ('BFB3351','Ace Practice · Corporate Social Responsibility',5,'A materiality assessment helps an organisation:',ARRAY['Prioritise sustainability topics that are significant to the organisation and its stakeholders','Avoid disclosing any negative impacts','Select topics only because they are easy to measure','Replace consultation with advertising']::text[],0,'Materiality helps prioritise significant impacts and topics; the specific approach depends on the reporting framework used.',5),
 -- Cross Cultural Management
 ('BFB3401','Ace Practice · Cross Cultural Management',1,'Cultural intelligence is best understood as the ability to:',ARRAY['Adapt effectively across cultural contexts while learning and avoiding assumptions','Memorise stereotypes about every nationality','Assume everyone from one country behaves identically','Avoid communicating with unfamiliar groups']::text[],0,'Cultural intelligence combines awareness, knowledge, motivation and behaviour that support effective cross-cultural interaction.',1),
 ('BFB3401','Ace Practice · Cross Cultural Management',2,'A manager finds that a gesture interpreted positively in one country is offensive in another. The most useful response is to:',ARRAY['Seek local context and feedback, then adapt respectfully','Assume the other group is irrational','Repeat the gesture more forcefully','Ban all cross-border communication']::text[],0,'Meaning depends on context; asking, listening and adapting is safer than imposing one interpretation.',2),
 ('BFB3401','Ace Practice · Cross Cultural Management',3,'Which practice helps a multinational team reduce misunderstanding?',ARRAY['Agreeing explicit communication norms, decision rights and ways to raise concerns','Relying on unspoken assumptions','Treating silence as agreement in every culture','Discouraging clarification questions']::text[],0,'Explicit norms and psychologically safe clarification reduce ambiguity in diverse teams.',3),
 ('BFB3401','Ace Practice · Cross Cultural Management',4,'Local adaptation in international management should be guided primarily by:',ARRAY['Evidence about local customers, institutions and norms while respecting core ethical standards','A stereotype about the national culture','A refusal to gather local feedback','Copying every practice from headquarters regardless of context']::text[],0,'Evidence-led adaptation improves fit while ethical and legal requirements remain binding.',4),
 ('BFB3401','Ace Practice · Cross Cultural Management',5,'Why is it risky to label an entire national culture as having one fixed communication style?',ARRAY['Individuals, organisations and situations vary, so broad labels can become stereotypes','Culture never influences communication','All cross-cultural differences can be solved by translation software','National identity perfectly predicts individual behaviour']::text[],0,'Cultural frameworks can prompt questions but should not be used to assume every individual behaves the same way.',5),
 -- Corporate Governance
 ('BFB3451','Ace Practice · Corporate Governance',1,'The board’s governance role is primarily to:',ARRAY['Provide oversight, set direction with management and hold executives accountable','Manage every routine transaction personally','Guarantee that no business risk exists','Replace audited financial statements with informal updates']::text[],0,'Boards oversee strategy, risk, management performance and accountability while management runs day-to-day operations.',1),
 ('BFB3451','Ace Practice · Corporate Governance',2,'A director has a material personal interest in a transaction involving the company. Good governance requires:',ARRAY['Disclosure and management of the conflict under applicable law and policy','Concealment until the contract is complete','Automatic approval without review','Deletion of the board minutes']::text[],0,'Disclosure and appropriate conflict-management procedures support fair decision-making and legal compliance.',2),
 ('BFB3451','Ace Practice · Corporate Governance',3,'Transparent corporate disclosure is valuable because it:',ARRAY['Helps shareholders and other authorised stakeholders assess performance, risks and accountability','Guarantees the share price will rise','Removes all commercial uncertainty','Means confidential personal data should be published']::text[],0,'Timely, accurate disclosure supports informed decisions and accountability while respecting lawful confidentiality and privacy.',3),
 ('BFB3451','Ace Practice · Corporate Governance',4,'Which action best supports effective board oversight of risk?',ARRAY['Receiving reliable risk information, challenging assumptions and monitoring mitigation','Accepting management assurances without review','Removing risk from board agendas','Measuring only the number of meetings']::text[],0,'Oversight requires relevant information, constructive challenge and follow-up on risk responses.',4),
 ('BFB3451','Ace Practice · Corporate Governance',5,'Why should a board distinguish oversight from day-to-day management?',ARRAY['Clear roles preserve accountability while allowing the board to challenge and monitor management','The board should never ask management questions','Managers should make all shareholder decisions','Oversight means avoiding strategy and risk discussions']::text[],0,'Clear responsibilities help the board monitor management without obscuring who is accountable for execution.',5),
 -- Management Research Project
 ('BFC3475','Ace Practice · Management Research Project',1,'A strong research question should be:',ARRAY['Focused, researchable and clear about the issue or relationship being investigated','So broad that no evidence can answer it','Written only after results are known','A statement that assumes the desired conclusion']::text[],0,'A focused research question defines a manageable problem and guides design, evidence collection and analysis.',1),
 ('BFC3475','Ace Practice · Management Research Project',2,'A literature review is intended mainly to:',ARRAY['Synthesize existing knowledge, concepts, evidence and gaps relevant to the research problem','List sources without evaluating relevance','Replace collection of any new data in every study','Guarantee the hypothesis is correct']::text[],0,'A literature review positions the project within existing work, clarifies concepts and identifies gaps or debates.',2),
 ('BFC3475','Ace Practice · Management Research Project',3,'A sample excludes all customers who do not use smartphones, but the study aims to describe all customers. The main risk is:',ARRAY['Coverage bias because part of the target population is systematically excluded','A guaranteed increase in validity','Perfect random sampling','An automatic reduction in every type of error']::text[],0,'If the sampling frame excludes relevant people, results may not represent the full target population.',3),
 ('BFC3475','Ace Practice · Management Research Project',4,'Before collecting identifiable information from participants, a researcher should consider:',ARRAY['Informed consent, privacy, data security and the applicable ethics-approval requirements','Whether participants can be kept unaware of the study in every case','Publishing personal details by default','Skipping any review because the sample is small']::text[],0,'Research ethics requires appropriate consent, confidentiality, data protection and any required institutional review.',4),
 ('BFC3475','Ace Practice · Management Research Project',5,'A researcher reports that two variables are associated in a survey. Which conclusion is justified without stronger design or evidence?',ARRAY['The variables are associated in the observed data, but causation is not established','One variable definitely causes the other','The relationship must hold for every population','No further limitations need to be discussed']::text[],0,'Observational association alone does not establish causal direction or rule out confounding and selection effects.',5),
 -- Project Portfolio Management
 ('BFB3411','Ace Practice · Project Portfolio Management',1,'Project portfolio management differs from managing one project because it primarily seeks to:',ARRAY['Select and balance projects collectively to support strategy, resources and overall risk','Maximise the budget of every project independently','Avoid comparing project benefits','Ensure every proposed project is approved']::text[],0,'Portfolio management makes coordinated investment and prioritisation decisions across projects to optimise strategic value.',1),
 ('BFB3411','Ace Practice · Project Portfolio Management',2,'Two proposed projects require the same scarce specialist team during the same period. Portfolio governance should first:',ARRAY['Assess strategic priority, dependencies, capacity and trade-offs before committing both schedules','Approve both and assume capacity will expand automatically','Hide the conflict from sponsors','Choose the project with the longest title']::text[],0,'Portfolio decisions account for shared constraints, dependencies and relative contribution to strategic objectives.',2),
 ('BFB3411','Ace Practice · Project Portfolio Management',3,'A project is on time and within budget but no longer supports the organisation’s strategy. Portfolio review should:',ARRAY['Reassess its continued priority and expected benefits against the portfolio objectives','Continue automatically because schedule performance is good','Ignore strategic changes until project closure','Remove all outcome measures']::text[],0,'A project can be efficiently delivered yet no longer be the best use of scarce resources if strategic conditions change.',3),
 ('BFB3411','Ace Practice · Project Portfolio Management',4,'Why should portfolio managers monitor benefits after project delivery?',ARRAY['The intended organisational value may depend on adoption and operational changes after delivery','Benefits are always realised as soon as a project is marked complete','Monitoring benefits is identical to checking invoices only','A business case never changes after approval']::text[],0,'Benefits often depend on post-delivery adoption, process changes and sustained measurement.',4),
 ('BFB3411','Ace Practice · Project Portfolio Management',5,'Portfolio risk is especially important when:',ARRAY['Several projects share dependencies or are exposed to the same external event','Every project is completely isolated by definition','Only one project exists and it has no uncertainty','All projects have identical expected benefits and resource needs']::text[],0,'Correlated risks and dependencies can affect several projects together, so portfolio-level exposure can differ from each project’s standalone risk.',5)
),
questions_added AS (
 INSERT INTO public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order)
 SELECT q.id,qs.prompt,to_jsonb(qs.options),qs.correct_index,qs.explanation,qs.sort_order
 FROM question_seed qs JOIN quiz_ids q ON q.course_code=qs.course_code AND q.title=qs.quiz_title
 WHERE NOT EXISTS(SELECT 1 FROM public.ace_questions existing WHERE existing.quiz_id=q.id)
 RETURNING id
)
SELECT (SELECT count(*) FROM inserted_quizzes) quizzes_created,
       (SELECT count(*) FROM questions_added) questions_created;